{
  "correction_rules": [
    "Reduce forecast overshoots following strong upward sentiment spikes (e.g., sentiment > 0.20) by 10-15% to avoid overreaction.",
    "Adjust downward forecasts when sentiment is negative (e.g., sentiment < 0.0) by adding a 5-10% bias correction to reflect bearish momentum.",
    "Apply mean reversion bias: if forecast deviates > 10% from recent 5-day average, adjust toward the average by 5-7% per day.",
    "For long-term (30-day) forecasts, reduce volatility by smoothing out extreme highs/lows with a 3-point moving average filter.",
    "When sentiment is neutral (0.0), prioritize historical trend alignment over model extrapolation; use 10-day moving average as anchor.",
    "Correct for lag: if true outcome is significantly lower than forecast after 3-5 days, reduce next-day forecast by 5-8% to account for delayed market reaction."
  ]
}
